resource "aws_s3_bucket_versioning" "invoices" {
  bucket = aws_s3_bucket.invoices.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket" "statement_archive" {
  bucket = "${local.prefix}-statement-archive"
  tags   = local.tags
}

resource "aws_s3_bucket_public_access_block" "statement_archive" {
  bucket                  = aws_s3_bucket.statement_archive.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "statement_archive" {
  bucket = aws_s3_bucket.statement_archive.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "statement_archive" {
  bucket = aws_s3_bucket.statement_archive.id
  rule {
    id     = "to-glacier"
    status = "Enabled"
    filter {}
    transition {
      days          = 90
      storage_class = "GLACIER"
    }
  }
}
